head.script:
scwin.onpageload = function() {
    windowContainer1.createWindow({
        windowId : 'a1',
        title : 'title01',
        src : '/content/window/sub1.xml',
        openAction : 'existWindow',
        frameMode : "wframe",
        accessibility: "true"
    });

    windowContainer1.createWindow({
        windowId : 'a2',
        title : 'title02',
        src : '/content/window/sub2.xml',
        openAction : 'existWindow',
        frameMode : "wframe"
    });

    windowContainer1.createWindow({
        windowId : 'a3',
        title : 'title03',
        src : '/content/window/sub3.xml',
        openAction : 'existWindow',
        frameMode : "wframe"
    });

    windowContainer1.createWindow({
        windowId : 'a4',
        title : 'title04',
        src : '/content/window/sub4.xml',
        openAction : 'existWindow',
        frameMode : "wframe"
    });


    windowContainer1.setFocus(2);

};
scwin.windowContainer1_ondragstart = function(id) {
	localStorage.setItem('log1', 'ondragstart')
	console.log("ondragstart : " + id)
}
scwin.windowContainer1_ondragend = function(id) {
	localStorage.setItem('log2', 'ondragend')
	console.log("ondragend : " + id)
}

		scwin.simulateWrapper = function(target, type, options) {
			WebSquare.wUnit.getJq(target).simulate(type, options);
		}
		scwin.setSimulate = function() {
			scwin.simulateWrapper('#windowContainer1_subWindow0_header', 'drag-n-drop', {
				dx: 100,
				dy: 0
			});
		}

		scwin.checkVal1 = function() {
			return localStorage.getItem('log1') == 'ondragstart';
		}
		scwin.checkVal2 = function() {
			return localStorage.getItem('log2') == 'ondragend';
		}	
		scwin.unitTest = function() {
			//Unit
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_sequential').click()");
			WebSquare.wUnit.addCommand("pause", "400");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow0_header').click()");
			WebSquare.wUnit.addCommand("pause", "400");			
			WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
			WebSquare.wUnit.addCommand("pause", "500");

			WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
			WebSquare.wUnit.addCommand("pause", "500");		

			//Run test and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
		scwin.unitTest()
		localStorage.removeItem("log1");	
		localStorage.removeItem("log2");
